('0041a575-c6fd-4a7e-b9c3-56cc50e201d6', '{"en":"Seodaemun Independence Park"}', '{"en":"This historic park contains Independence Gate and memorials to Korean independence activists. Seodaemun Prison History Hall explains the site''s colonial history."}', 'park', NULL, '[]', 1, 'Seoul', '251, Tongil-ro, Seodaemun-gu, Seoul', 37.5752858, 126.9550192, '[]', '["https://english.visitseoul.net/attractions/Seodaemun-Independence-Park/ENP001753","https://www.wikidata.org/wiki/Q623629"]'),
('cbd403a4-1912-45b8-8ae1-fc13b4c2f1e5', '{"en":"Gyeongbokgung Palace"}', '{"en":"Built in 1395, Gyeongbokgung served as the main palace of the Joseon dynasty. Its grounds contain restored royal buildings and courtyards."}', 'culture', NULL, '["/pilot/cbd403a4-1912-45b8-8ae1-fc13b4c2f1e5.jpg"]', 1, 'Seoul', '161, Sajik-ro, Jongno-gu, Seoul', 37.5798841, 126.9767996, '[{"url":"/pilot/cbd403a4-1912-45b8-8ae1-fc13b4c2f1e5.jpg","author":"Seoul Tourism Archive","license":"KOGL Type 1","licenseUrl":"https://www.kogl.or.kr/info/licenseType1.do","sourceUrl":"https://commons.wikimedia.org/wiki/File:%EA%B4%91%ED%99%94%EB%AC%B8_%EC%9B%94%EB%8C%80.jpg","takenAt":"2023-10-16"}]', '["https://english.visitseoul.net/attractions/Gyeongbokgung-Palace_/72","https://www.wikidata.org/wiki/Q482485"]'),
('f0fcf98e-76d7-4673-b8c3-6baf519a1551', '{"en":"Cheonggyecheon Stream"}', '{"en":"This restored stream runs through central Seoul with paths below street level. Access can close during rain for safety."}', 'nature', NULL, '["/pilot/f0fcf98e-76d7-4673-b8c3-6baf519a1551.jpg"]', 1, 'Seoul', '37, Mugyo-ro, Jongno-gu, Seoul', 37.56902, 126.97771, '[{"url":"/pilot/f0fcf98e-76d7-4673-b8c3-6baf519a1551.jpg","author":"Pauloleong2002","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Cheonggyecheon_in_Korea.jpg","takenAt":"2014-10-29"}]', '["https://english.visitseoul.net/attractions/Cheonggyecheon-Stream_/35","https://www.wikidata.org/wiki/Q495437"]');
